SELECT txn_type, HOUR(txn_time) AS txn_hour, TO_DATE(txn_time) AS txn_day, ROUND((100 * SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_debit, COUNT(amount) AS amount_count, ROUND((100 * SUM(CASE WHEN merchant = 'Starbucks' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_starbucks FROM transactions WHERE is_flagged = FALSE GROUP BY txn_type, HOUR(txn_time), TO_DATE(txn_time);
